class Task:
    def __init__(self, C_k, D_k, T_k):
        self.C = C_k
        self.D = D_k
        self.T = T_k

class Job:
    def __init__(self, task_k, release_time):
        self.task = task_k
        self.release_time = release_time
        self.absolute_deadline = release_time + task_k.D
        self.finish_time = None # To be determined by scheduler

class Task:
    # ... (previous init)
    def get_utilization(self):
        return self.C / self.T
    def get_density(self):
        return self.C / self.D

def compute_total_utilization(task_set):
    U_tot = 0
    for task in task_set:
        U_tot += task.get_utilization()
    return U_tot

def compute_total_density(task_set):
    lambda_tot = 0
    for task in task_set:
        lambda_tot += task.get_density()
    return lambda_tot

def compute_max_utilization(task_set):
    U_max = 0
    for task in task_set:
        U_max = max(U_max, task.get_utilization())
    return U_max

def compute_max_density(task_set):
    lambda_max = 0
    for task in task_set:
        lambda_max = max(lambda_max, task.get_density())
    return lambda_max

class Task:
    # ... (previous init)
    def calculate_slack(self, job_finish_times, job_release_times):
        min_slack = float('inf')
        for j in range(len(job_finish_times)):
            job_deadline = job_release_times[j] + self.D
            min_slack = min(min_slack, job_deadline - job_finish_times[j])
        return min_slack

    def calculate_response_time(self, job_finish_times, job_release_times):
        max_response_time = 0
        for j in range(len(job_finish_times)):
            max_response_time = max(max_response_time, job_finish_times[j] - job_release_times[j])
        return max_response_time

def calculate_interference_on_k(task_k, interval_start, interval_end, system_state):
    interference_time = 0
    for t in range(interval_start, interval_end):
        if system_state.is_task_backlogged(task_k, t) and system_state.all_processors_busy(t):
            interference_time += 1 # Assuming discrete time ticks
    return interference_time

def calculate_interference_of_i_on_k(task_i, task_k, interval_start, interval_end, system_state):
    interference_time = 0
    for t in range(interval_start, interval_end):
        if system_state.is_task_backlogged(task_k, t) and system_state.is_task_executing(task_i, t):
            interference_time += 1
    return interference_time

def calculate_R_max_k_FP_old(task_k, task_set, m):
    R_max_k = task_k.C
    while True:
        prev_R_max_k = R_max_k
        interference_sum = 0
        for task_j in task_set:
            if task_j.priority > task_k.priority: # Assuming higher value means higher priority
                # ceil(R_max_k / T_j) * C_j + C_j
                interference_sum += (math.ceil(R_max_k / task_j.T) * task_j.C) + task_j.C

        R_max_k = task_k.C + math.floor(interference_sum / m)

        if R_max_k == prev_R_max_k:
            break
        # Optional: check for R_max_k > task_k.D to stop early if unschedulable
        if R_max_k > task_k.D:
            return float('inf') # Unschedulable
    return R_max_k

def calculate_R_ub_k_EDF(task_k, task_set, m):
    R_ub_k = task_k.C
    while True:
        prev_R_ub_k = R_ub_k
        total_interference_sum = 0
        for task_i in task_set:
            if task_i != task_k:
                # Term 1: W_i(R_ub_k) from Theorem 4
                term1 = calculate_workload_bound(task_i, R_ub_k)

                # Term 2: I_i_k(D_k) from Theorem 5 (only if R_ub_k <= D_k)
                term2 = float('inf')
                if R_ub_k <= task_k.D:
                    term2 = calculate_edf_interference_bound(task_i, task_k)

                # Term 3: R_ub_k - C_k + 1
                term3 = R_ub_k - task_k.C + 1

                I_hat_i_k_R_ub_k = min(term1, term2, term3)
                total_interference_sum += I_hat_i_k_R_ub_k

        R_ub_k = task_k.C + math.floor(total_interference_sum / m)

        if R_ub_k == prev_R_ub_k:
            break
        if R_ub_k > task_k.D:
            return float('inf') # Unschedulable
    return R_ub_k
